const item = $input.first().json;
const body = item.body && typeof item.body === 'object' ? item.body : item;
const kind = String(body.kind || 'chaos_report_adhoc');
const ts = new Date().toISOString();
return [
  {
    json: {
      ok: true,
      received_at_utc: ts,
      kind,
      rto_s_observed: body.rto_s_observed != null ? body.rto_s_observed : null,
      probe_ts: body.probe_ts || null,
      recovery_ts: body.recovery_ts || null,
      notes: body.notes || '',
      raw: body
    }
  }
];
